// TEST1e12 canonical specimen generated by TestPrivateTypedOwnerFixtureV2 using
// existing fixtureV2/sealV2/kernel.initialize. Not a production funding factory.
// Generation log: typed-owner-3khugszu/fixture.log; bytes are frozen, not resealed.
const typedOwnerFixtureV2 = ""

type typedOwnerFixtureDocumentV2 struct {
	Job   []byte
	Head  string
	Files map[string][]byte
}

func typedOwnerRootV2(t *testing.T) (*inv.PrivateTypedBundleOwnerV2, *publication.Root, typedOwnerFixtureDocumentV2, string) {
	t.Helper()
	var f typedOwnerFixtureDocumentV2
	zipped, err := base64.StdEncoding.DecodeString(typedOwnerFixtureV2)
	if err != nil {
		t.Fatal(err)
	}
	gz, err := gzip.NewReader(bytes.NewReader(zipped))
	if err != nil {
		t.Fatal(err)
	}
	defer gz.Close()
	raw, err := io.ReadAll(io.LimitReader(gz, 64<<10))
	if err != nil {
		t.Fatal(err)
	}
	var frozen struct {
		Job   string
		Head  string
		Files map[string]string
	}
	if err = json.Unmarshal(raw, &frozen); err != nil {
		t.Fatal(err)
	}
	f.Job = []byte(frozen.Job)
	f.Head = frozen.Head
	f.Files = map[string][]byte{}
	for s, b := range frozen.Files {
		f.Files[s] = []byte(b)
	}
	path := t.TempDir()
	if err := os.Chmod(path, 0700); err != nil {
		t.Fatal(err)
	}
	current := ""
	for s, b := range f.Files {
		p := filepath.Join(path, filepath.FromSlash(s))
		if err := os.MkdirAll(filepath.Dir(p), 0700); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, b, 0600); err != nil {
			t.Fatal(err)
		}
		if strings.Contains(s, "/current/") {
			current = s
		}
	}
	root, err := publication.OpenRoot(path)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { root.Close() })
	owner, err := inv.OpenPrivateTypedBundleOwnerV2(context.Background(), root, f.Job, f.Head, inv.PrivateManagedInputVerificationV2{Records: 4096, Bytes: 64 << 20, Work: 16384})
	if err != nil {
		t.Fatal(err)
	}
	return owner, root, f, current
}
func typedOwnerBindingV2(t *testing.T, head string) (inv.PrivateTypedBundleBindingV2, []byte) {
	t.Helper()
	req, _ := bundleRequest(t, 7, "H")
	b, err := pc.NewGroupingCaseBundlePrivate(req)
	if err != nil {
		t.Fatal(err)
	}
	expected, err := pc.NewGroupingBundleExpectationPrivate(b)
	if err != nil {
		t.Fatal(err)
	}
	if out := os.Getenv("TYPED_OWNER_BUNDLE_OUT"); out != "" {
		if err := os.WriteFile(out, b.CanonicalBytes(), 0600); err != nil {
			t.Fatal(err)
		}
	}
	direct, err := b.ExecuteReport()
	if err != nil {
		t.Fatal(err)
	}
	if err = b.CheckReport(direct.CanonicalBytes()); err != nil {
		t.Fatal(err)
	}
	return inv.PrivateTypedBundleBindingV2{Expected: expected, Candidate: b.CanonicalBytes(), Attempt: fmt.Sprintf("sha256:%x", sha256.Sum256([]byte(t.Name()))), Head: head, Deadline: time.Now().Add(20 * time.Second)}, direct.CanonicalBytes()
}
func typedOwnerHeadV2(t *testing.T, r *publication.Root, s string) map[string]json.RawMessage {
	t.Helper()
	raw, err := r.ReadSelector(s, 64<<10)
	if err != nil {
		t.Fatal(err)
	}
	var h map[string]json.RawMessage
	if err = json.Unmarshal(raw, &h); err != nil {
		t.Fatal(err)
	}
	return h
}
func TestTypedBundleOwnerBaselineV2(t *testing.T) {
	_, _, f, _ := typedOwnerRootV2(t)
	q, direct := typedOwnerBindingV2(t, f.Head)
	trace := pc.ObserveTypedOwnerForTest(t)
	got, _, failed := pc.ExecuteGroupingCaseBundleSupervisedPrivate(context.Background(), q.Expected, q.Candidate)
	if failed != nil || !bytes.Equal(got, direct) || trace().Delivered != 1 || trace().Reaped != 1 {
		t.Fatalf("ASSERT_TYPED_OWNER_WORKER_BASELINE: failure=%v bytes=%d trace=%+v", failed, len(got), trace())
	}
	t.Log("ASSERT_TYPED_OWNER_WORKER_BASELINE: PASS")
}
func TestTypedBundleOwnerSuccessV2(t *testing.T) {
	owner, root, f, current := typedOwnerRootV2(t)
	q, direct := typedOwnerBindingV2(t, f.Head)
	trace := pc.ObserveTypedOwnerForTest(t)
	operation, err := owner.Reserve(context.Background(), q)
	if err != nil {
		t.Fatal(err)
	}
	got, _, failed := owner.Execute(context.Background(), operation, q)
	h := typedOwnerHeadV2(t, root, current)
	if failed != nil || !bytes.Equal(got, direct) || string(h["disposition"]) != `"OBSERVED"` || trace().Delivered != 1 || trace().Reaped != 1 {
		t.Fatalf("ASSERT_TYPED_OWNER_EXACT_OBSERVED: failure=%v bytes=%d head=%s trace=%+v", failed, len(got), h["disposition"], trace())
	}
	again, _, f2 := owner.Execute(context.Background(), operation, q)
	if again != nil || f2 == nil || trace().Delivered != 1 {
		t.Fatal("ASSERT_TYPED_OWNER_COPY_RETIRED")
	}
	t.Log("ASSERT_TYPED_OWNER_EXACT_OBSERVED: PASS")
	t.Log("ASSERT_TYPED_OWNER_COPY_RETIRED: PASS")
	second := q
	if err := json.Unmarshal(h["identity"], &second.Head); err != nil {
		t.Fatal(err)
	}
	second.Attempt = fmt.Sprintf("sha256:%x", sha256.Sum256([]byte(t.Name()+"second-paid")))
	second.Deadline = time.Now().Add(20 * time.Second)
	op2, err := owner.Reserve(context.Background(), second)
	if err != nil {
		t.Fatal(err)
	}
	got2, _, failed2 := owner.Execute(context.Background(), op2, second)
	h2 := typedOwnerHeadV2(t, root, current)
	if failed2 != nil || !bytes.Equal(got2, direct) || string(h2["consumed_windows"]) != "2" || trace().Delivered != 2 || trace().Reaped != 2 {
		t.Fatalf("ASSERT_ORDINARY_NEXT_PAID_OPERATION: failure=%v head=%s trace=%+v", failed2, h2["consumed_windows"], trace())
	}
	t.Log("ASSERT_ORDINARY_NEXT_PAID_OPERATION: PASS")
}

func TestTypedBundleOwnerNoConfirmationV2(t *testing.T) {
	owner, _, f, _ := typedOwnerRootV2(t)
	q, _ := typedOwnerBindingV2(t, f.Head)
	pidfile := filepath.Join(t.TempDir(), "preconfirmation-worker.json")
	t.Setenv("PROGRAMC_TEST_WORKER", "typed-stage-record")
	t.Setenv("PROGRAMC_TEST_PIDFILE", pidfile)
	trace := pc.ObserveTypedOwnerForTest(t)
	got, _, failed := owner.Execute(context.Background(), inv.PrivateTypedBundleOperationV2{}, q)
	_, pidErr := os.Stat(pidfile)
	if got != nil || failed == nil || trace().Delivered != 0 || trace().Reaped != 0 || !os.IsNotExist(pidErr) {
		t.Fatalf("ASSERT_CONFIRMED_RESERVE_BEFORE_EFFECTS: bytes=%d failure=%v trace=%+v actual_SELF_PID_marker=%v", len(got), failed, trace(), pidErr == nil)
	}
	t.Log("ASSERT_CONFIRMED_RESERVE_BEFORE_EFFECTS: PASS")
}

func TestTypedBundleOwnerOrderedScheduleV2(t *testing.T) {
	// Preregistered controlled schedule: mask order 1..7, probes H/U/L/B/N,
	// seeds 7 then 19. Exactly the existing component schedule, not a pilot change.
	first := pc.GroupingCaseBundleRequestPrivate{Schema: pc.GroupingCaseBundleSchemaPrivate, BatchID: "owner-35-seed7", ImplementationID: "controlled-not-qualified", ImplementationBytes: []byte("exact LF declaration\n")}
	second := first
	second.BatchID = "owner-35-seed19"
	combined := first
	combined.BatchID = "owner-70-bounded-refusal"
	for mask := 1; mask < 8; mask++ {
		for _, probe := range []string{"H", "U", "L", "B", "N"} {
			r, _ := bundleRequest(t, mask, probe)
			s := r.Slots[0]
			first.Slots = append(first.Slots, s)
			combined.Slots = append(combined.Slots, s)
			input, e := rg.ParseAndAdmit(s.InputBytes, s.Predecessors, rg.ParseLimits{MaxRawBytes: 1 << 20, MaxArtifacts: 16, MaxNodes: 8192, MaxOccurrences: 4096, MaxContributions: 4096, MaxCanonicalBytes: 1 << 20, MaxStringBytes: 4096})
			if e != nil {
				t.Fatal(e)
			}
			s.Seed = 19
			s.CaseID += "-seed19"
			c, e := pc.NewGroupingEvaluationCasePrivate(pc.GroupingEvaluationCaseRequestPrivate{CaseID: s.CaseID, SelectorID: s.SelectorID, RunID: s.RunID, SelectorBytes: s.SelectorBytes, Input: input, Policy: evaluationPolicy(t, probe), ProjectionLimits: s.ProjectionLimits, Seed: s.Seed})
			if e != nil {
				t.Fatal(e)
			}
			j, e := pc.NewGroupingJudgmentsPrivate(c, s.JudgmentID, s.Pairs)
			if e != nil {
				t.Fatal(e)
			}
			s.CaseBytes = c.CanonicalBytes()
			s.JudgmentBytes = j.CanonicalBytes()
			second.Slots = append(second.Slots, s)
			combined.Slots = append(combined.Slots, s)
		}
	}
	if _, e := pc.NewGroupingCaseBundlePrivate(combined); e == nil {
		t.Fatal("ASSERT_OWNER_COMBINED_70_BOUND_REFUSED")
	}
	for _, request := range []pc.GroupingCaseBundleRequestPrivate{first, second} {
		t.Run(request.BatchID, func(t *testing.T) {
			owner, root, f, current := typedOwnerRootV2(t)
			b, e := pc.NewGroupingCaseBundlePrivate(request)
			if e != nil {
				t.Fatal(e)
			}
			expected, e := pc.NewGroupingBundleExpectationPrivate(b)
			if e != nil {
				t.Fatal(e)
			}
			direct, e := b.ExecuteReport()
			if e != nil {
				t.Fatal(e)
			}
			if e = b.CheckReport(direct.CanonicalBytes()); e != nil {
				t.Fatal(e)
			}
			q := inv.PrivateTypedBundleBindingV2{Expected: expected, Candidate: b.CanonicalBytes(), Attempt: fmt.Sprintf("sha256:%x", sha256.Sum256([]byte(request.BatchID))), Head: f.Head, Deadline: time.Now().Add(30 * time.Second)}
			op, e := owner.Reserve(context.Background(), q)
			if e != nil {
				t.Fatal(e)
			}
			report, _, failed := owner.Execute(context.Background(), op, q)
			h := typedOwnerHeadV2(t, root, current)
			if failed != nil || !bytes.Equal(report, direct.CanonicalBytes()) || string(h["disposition"]) != `"OBSERVED"` {
				t.Fatalf("ASSERT_OWNER_ORDERED_EXACT_REPORT: failure=%v bytes=%d", failed, len(report))
			}
			t.Logf("ASSERT_OWNER_ORDERED_EXACT_REPORT: PASS slots=%d seed=%d bytes=%d sha256=%x", len(request.Slots), request.Slots[0].Seed, len(report), sha256.Sum256(report))
		})
	}
}

func TestTypedBundleOwnerStageFailuresV2(t *testing.T) {
	for _, phase := range []string{"execution", "replay"} {
		for _, mode := range []string{"cancel", "wall", "rss", "cleanup"} {
			t.Run(phase+"-"+mode, func(t *testing.T) {
				owner, root, f, current := typedOwnerRootV2(t)
				b := pc.TypedOwnerStageBundleForTest(t)
				expected, e := pc.NewGroupingBundleExpectationPrivate(b)
				if e != nil {
					t.Fatal(e)
				}
				stage := filepath.Join(t.TempDir(), "stage.jsonl")
				pidfile := filepath.Join(t.TempDir(), "worker.json")
				workerMode := "typed-stage-" + phase
				if mode == "rss" {
					workerMode += "-rss"
				}
				t.Setenv("PROGRAMC_TEST_WORKER", workerMode)
				t.Setenv("PROGRAMC_TEST_STAGE_FILE", stage)
				t.Setenv("PROGRAMC_TEST_PIDFILE", pidfile)
				t.Setenv("PROGRAMC_TEST_PARENT_WATCHDOG", "1")
				q := inv.PrivateTypedBundleBindingV2{Expected: expected, Candidate: b.CanonicalBytes(), Attempt: fmt.Sprintf("sha256:%x", sha256.Sum256([]byte(t.Name()))), Head: f.Head, Deadline: time.Now().Add(6 * time.Second)}
				op, e := owner.Reserve(context.Background(), q)
				if e != nil {
					t.Fatal(e)
				}
				trace := pc.ObserveTypedOwnerForTest(t)
				run := func() {
					ctx, cancel := context.WithCancel(context.Background())
					defer cancel()
					type terminal struct {
						report []byte
						failed *pc.SupervisionFailure
					}
					done := make(chan terminal, 1)
					go func() { report, _, failed := owner.Execute(ctx, op, q); done <- terminal{report, failed} }()
					reached := false
					for time.Now().Before(q.Deadline) {
						raw, _ := os.ReadFile(stage)
						if bytes.Contains(raw, []byte(`"Phase":"`+phase+`"`)) {
							reached = true
							break
						}
						time.Sleep(5 * time.Millisecond)
					}
					if (mode != "wall" && mode != "rss") || !reached {
						cancel()
					}
					var result terminal
					select {
					case result = <-done:
					case <-time.After(9 * time.Second):
						t.Fatal("stage SELF operation did not return")
					}
					if !reached {
						t.Fatal("ASSERT_REAL_TYPED_STAGE_REACHED")
					}
					if mode == "rss" && (result.failed == nil || result.failed.Code != pc.CodeMemoryLimit) {
						t.Fatalf("ASSERT_STAGE_REAL_RSS_FAILURE: %v", result.failed)
					}
					if result.report != nil || result.failed == nil {
						t.Fatalf("ASSERT_STAGE_FAILURE_NIL_REPORT: bytes=%d failure=%v", len(result.report), result.failed)
					}
					h := typedOwnerHeadV2(t, root, current)
					if string(h["disposition"]) != `"PENDING"` || string(h["consumed_windows"]) != "1" {
						t.Fatalf("ASSERT_STAGE_PENDING_CHARGE: %s", h["disposition"])
					}
					if mode == "cleanup" {
						if result.failed.Code != pc.CodeCleanupFailure || trace().Reaped != 0 {
							t.Fatalf("ASSERT_CLEANUP_NO_FALSE_REAP: failure=%v trace=%+v", result.failed, trace())
						}
					} else {
						if trace().Reaped != 1 {
							t.Fatalf("ASSERT_STAGE_ACTUAL_REAP: %+v failure=%v", trace(), result.failed)
						}
						pc.VerifyTypedOwnerGoneForTest(t, pidfile)
					}
					again := q
					again.Attempt = fmt.Sprintf("sha256:%x", sha256.Sum256([]byte(t.Name()+"retry")))
					if _, e := owner.Reserve(context.Background(), again); e == nil {
						t.Fatal("ASSERT_STAGE_OWNER_STOP")
					}
					t.Logf("ASSERT_REAL_TYPED_STAGE_REACHED: PASS phase=%s mode=%s failure=%s delivered=%d supervisor_reaped=%d", phase, mode, result.failed.Code, trace().Delivered, trace().Reaped)
				}
				if mode == "cleanup" {
					pc.WithTypedOwnerCleanupFaultForTest(t, pidfile, run)
				} else {
					run()
				}
			})
		}
	}
}
